def calc_my_rsi(close, period=14):
    delta = close.diff()
    gain = delta.where(delta > 0, 0.0).ewm(alpha=1/period).mean()
    loss = (-delta).where(delta < 0, 0.0).ewm(alpha=1/period).mean()
    rs = gain / loss
    return 100 - (100 / (1 + rs))

def calc_volume_ratio(volume, period=20):
    ma_vol = volume.rolling(period).mean()
    return volume / ma_vol
